-- The demo gallery's placeholder artwork drew a lotus (a bud between two
-- pairs of petals). The couple asked for no lotus anywhere, so the seeded
-- placeholders are redrawn as a pair of wedding rings (lib/placeholder.ts).
--
-- Images are served as immutable by their id (browsers and the CDN keep them
-- for a year), so the new drawing goes into a NEW row and the gallery is
-- pointed at it; overwriting the old row in place would never reach anyone who
-- had already seen it. The old row is left as it is, in case anything else
-- points at it. Only demo images that still hold the old drawing are touched:
-- a photo the couple uploaded is never changed, and running this twice
-- changes nothing.
INSERT INTO "media" ("id", "wedding_id", "filename", "mime_type", "size", "kind", "data", "complete")
  SELECT "id" || '-rings', "wedding_id", "filename", "mime_type", 1335, "kind", decode('', 'hex'), true
  FROM "media" WHERE "filename" = 'demo-1.svg' AND "mime_type" = 'image/svg+xml' AND position('M0-96C24-52' in convert_from("data", 'UTF8')) > 0
  ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
UPDATE "gallery_images" SET "media_id" = "media_id" || '-rings'
  WHERE "media_id" IN (SELECT "id" FROM "media" WHERE "filename" = 'demo-1.svg' AND "mime_type" = 'image/svg+xml' AND position('M0-96C24-52' in convert_from("data", 'UTF8')) > 0)
    AND EXISTS (SELECT 1 FROM "media" m WHERE m."id" = "gallery_images"."media_id" || '-rings');
--> statement-breakpoint
